_SKILL_MANAGER_CLI = OPENCLAW_DIR / "scripts" / "tnode_skill_manager.py"


def _run_skill_manager(*args: str, timeout: int = 180) -> dict:
    """Corre `tnode_skill_manager.py <args>` y parsea su JSON (siempre JSON,
    también en error). OPENCLAW_HOME viaja tal cual: el CLI usa la semántica
    de los daemons (dir .openclaw), no la del CLI de openclaw."""
    if not _SKILL_MANAGER_CLI.is_file():
        return {"ok": False, "error": f"cli_not_found: {_SKILL_MANAGER_CLI}"}
    py = sys.executable or "python3"
    env = os.environ.copy()
    env["OPENCLAW_HOME"] = str(OPENCLAW_DIR)
    try:
        proc = subprocess.run(
            [py, str(_SKILL_MANAGER_CLI), *args],
            capture_output=True, text=True, timeout=timeout, check=False, env=env,
        )
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "timeout"}
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "error": str(e)[:300]}
    raw = (proc.stdout or "").strip()
    try:
        payload = json.loads(raw)
    except (TypeError, ValueError):
        return {"ok": False, "error": "bad_json", "code": proc.returncode,
                "stdout": raw[-500:], "stderr": (proc.stderr or "")[-500:]}
    payload.setdefault("ok", proc.returncode == 0)
    return payload


_SKILLS_CATALOG_PATH = OPENCLAW_DIR / "tnode-skills" / "catalog.json"
_SKILLS_CATALOG_LAST = 0.0
SKILLS_CATALOG_INTERVAL_S = float(os.environ.get("TNODE_SKILLS_CATALOG_S", "600"))


def _sync_skills_catalog(token: dict, force: bool = False) -> None:
    """P2 (2.1.0): punteros de skills del proyecto de este nodo
    (`skillsCatalog/{skill}` = version + sha256 + url en el espejo público).
    Se bajan a tnode-skills/catalog.json; si cambió, `tnode-skill-manager
    fetch` trae los paquetes al cache (verifica sha256) y `sync` los
    materializa. Cada 10 min; un fallo de red deja el archivo intacto y se
    reintenta al siguiente ciclo. Sin catálogo (proyecto sin docs) no toca
    nada: el cache horneado sigue mandando."""
    global _SKILLS_CATALOG_LAST
    now = time.time()
    if not force and (now - _SKILLS_CATALOG_LAST) < SKILLS_CATALOG_INTERVAL_S:
        return
    _SKILLS_CATALOG_LAST = now
    if not _SKILL_MANAGER_CLI.is_file():
        return
    try:
        url = f"{_firestore_base()}/skillsCatalog?pageSize=200"
        doc = _http_request("GET", url, headers={"Authorization": f"Bearer {token['idToken']}"}, timeout=30)
    except Exception as e:  # noqa: BLE001
        _log(f"skills-catalog: no se pudo leer skillsCatalog: {e}")
        return
    skills = {}
    for d in (doc or {}).get("documents") or []:
        f = _fs_unwrap({"mapValue": {"fields": d.get("fields") or {}}})
        name = f.get("skill") or d.get("name", "").rsplit("/", 1)[-1]
        if name and f.get("version") and f.get("sha256") and f.get("url"):
            skills[name] = {"version": f["version"], "sha256": f["sha256"], "url": f["url"],
                            "releaseTag": f.get("releaseTag")}
    if not skills:
        return
    body = json.dumps({"schema": 1, "project": PROJECT_ID, "skills": skills}, ensure_ascii=False, indent=2, sort_keys=True)
    try:
        prev = _SKILLS_CATALOG_PATH.read_text(encoding="utf-8") if _SKILLS_CATALOG_PATH.is_file() else ""
    except OSError:
        prev = ""
    if prev == body and not force:
        return
    try:
        _SKILLS_CATALOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        _SKILLS_CATALOG_PATH.write_text(body + "\n", encoding="utf-8")
    except OSError as e:
        _log(f"skills-catalog: no pude escribir catalog.json: {e}")
        return
    res = _run_skill_manager("fetch", "--catalog", str(_SKILLS_CATALOG_PATH), timeout=600)
    if not res.get("ok"):
        _log("skills-catalog: fetch: %s" % (res.get("summary") or res.get("error") or res)[:300])
        if res.get("errors"):
            _log("skills-catalog: errores: %s" % json.dumps(res["errors"], ensure_ascii=False)[:400])
    if res.get("fetched"):
        _log("skills-catalog: %s" % ", ".join("%s %s→%s" % (x["skill"], x.get("from"), x["to"]) for x in res["fetched"]))
        s2 = _run_skill_manager("sync")
        _log("skills: %s" % (s2.get("summary") or s2.get("error")))
        _sync_client_skills(force=True)
        _mirror_installed_skills(token, force=True)


_CLIENT_AGENTS = ("recepcion",)
_SKILLS_ZONE_BEGIN = "<!-- tnode-skills:begin -->"
_SKILLS_ZONE_END = "<!-- tnode-skills:end -->"
_CLIENT_SKILLS_LAST_SIG = None


def _sync_client_skills(force: bool = False) -> None:
    """P3 skill-manager. Para cada agente de clientes (recepcion):
    (a) allowlist del plugin: `channelSkillTools.<agente>` = unión de
        `client.tools` de las skills HABILITADAS ahí (openclaw config patch,
        idempotente). Nunca exec/read: recepcion los tiene denegados.
    (b) zona gestionada en su TOOLS.md con los bloques del CLI
        (`blocks --agent`), entre markers; el resto del archivo es del
        gateway y no se toca.
    Sin skills habilitadas la lista queda vacía y la zona se retira."""
    global _CLIENT_SKILLS_LAST_SIG
    if not _SKILL_MANAGER_CLI.is_file():
        return
    try:
        allow: dict = {}
        zones: dict = {}
        for agent in _a2a_client_agent_ids():
            res = _run_skill_manager("list", "--agent", agent)
            tools: list = []
            for sk in (res.get("skills") or []) if res.get("ok") else []:
                arec = (sk.get("agents") or {}).get(agent) or {}
                if not arec.get("enabled", True):
                    continue
                for t in ((sk.get("client") or {}).get("tools") or []):
                    if t not in tools:
                        tools.append(t)
            allow[agent] = tools
            b = _run_skill_manager("blocks", "--agent", agent)
            zones[agent] = "\n\n".join(x.get("text", "") for x in (b.get("blocks") or [])) if b.get("ok") else ""
        sig = json.dumps({"allow": allow, "zones": zones}, sort_keys=True)
        if sig == _CLIENT_SKILLS_LAST_SIG and not force:
            return
        # (a) plugin
        try:
            cfg = json.loads((OPENCLAW_DIR / "openclaw.json").read_text(encoding="utf-8"))
            entry = ((cfg.get("plugins") or {}).get("entries") or {}).get("tbrain-context-engine") or {}
            current = (entry.get("config") or {}).get("channelSkillTools") or {}
        except (OSError, ValueError):
            current = None
        if current is None or {k: sorted(v) for k, v in current.items()} != {k: sorted(v) for k, v in allow.items()}:
            r = _run_openclaw("config", "patch", "--stdin", timeout=60,
                              input_text=json.dumps({"plugins": {"entries": {"tbrain-context-engine": {
                                  "config": {"channelSkillTools": allow}}}}}))
            if r.get("ok"):
                _log("client-skills: channelSkillTools → %s" % json.dumps(allow, ensure_ascii=False))
            else:
                _log("client-skills: config patch falló: %s" % (r.get("stderr") or r.get("error") or "")[:200])
        # (b) TOOLS.md por agente
        for agent, zone in zones.items():
            ws = (_RECEPCION_WS_DIR if agent == "recepcion"
                  else (_a2a_target_workspace(agent) or (OPENCLAW_DIR / f"workspace-{agent}")))
            md = ws / "TOOLS.md"
            try:
                txt = md.read_text(encoding="utf-8") if md.is_file() else ""
            except OSError:
                txt = ""
            block = f"{_SKILLS_ZONE_BEGIN}\n{zone.strip()}\n{_SKILLS_ZONE_END}" if zone.strip() else ""
            if _SKILLS_ZONE_BEGIN in txt and _SKILLS_ZONE_END in txt:
                head, _, rest = txt.partition(_SKILLS_ZONE_BEGIN)
                _, _, tail = rest.partition(_SKILLS_ZONE_END)
                new_txt = (head.rstrip() + ("\n\n" + block if block else "") + tail).rstrip() + "\n"
            else:
                new_txt = (txt.rstrip() + "\n\n" + block + "\n") if block else txt
            if new_txt != txt:
                ws.mkdir(parents=True, exist_ok=True)
                md.write_text(new_txt, encoding="utf-8")
                _log(f"client-skills: TOOLS.md de {agent} — zona de skills {'escrita' if block else 'retirada'}")
        _CLIENT_SKILLS_LAST_SIG = sig
    except Exception as e:  # noqa: BLE001
        _log(f"client-skills: {e}")


_MIRROR_SKILLS_LAST_SIG = None


def _mirror_installed_skills(token: dict, force: bool = False) -> None:
    """Espejo por nodo de lo que el skill-manager tiene instalado:
    users/{uid}/nodes/{nodeId}/installed_skills/{skill} con los campos que
    la pantalla del dueño necesita (textos i18n, audiencia, agentes donde
    vive y si está habilitada en cada uno). Sólo MIS campos (updateMask):
    los docs de skills de tienda y el flujo `installing` del app no se
    tocan."""
    global _MIRROR_SKILLS_LAST_SIG
    if not _SKILL_MANAGER_CLI.is_file():
        return
    res = _run_skill_manager("list")
    if not res.get("ok"):
        return
    rows = res.get("skills") or []
    sig = json.dumps(rows, sort_keys=True, ensure_ascii=False)
    if sig == _MIRROR_SKILLS_LAST_SIG and not force:
        return
    cfg = load_config()
    base = (f"{_firestore_base()}/users/{token['uid']}/nodes/{cfg['nodeId']}/installed_skills")
    def _i18n(v):
        if isinstance(v, dict):
            return {"mapValue": {"fields": {k: {"stringValue": str(x)} for k, x in v.items() if isinstance(x, str)}}}
        return {"nullValue": None}
    ok = 0
    for sk in rows:
        # el CLI ya localizó los textos; para el app mandamos el objeto i18n
        # completo leyendo el manifest vivo
        try:
            _agent0 = next(iter(sk.get("agents") or {"main": {}}))
            _ws = OPENCLAW_DIR / "workspace" if _agent0 == "main" else OPENCLAW_DIR / f"workspace-{_agent0}"
            m = json.loads((_ws / "skills" / sk["name"] / "manifest.json").read_text(encoding="utf-8"))
        except (OSError, ValueError):
            m = {}
        agents = {a: {"mapValue": {"fields": {"enabled": {"booleanValue": bool((r or {}).get("enabled", True))}}}}
                  for a, r in (sk.get("agents") or {}).items()}
        fields = {
            "skillId": {"stringValue": sk["name"]},
            "managedBy": {"stringValue": "tnode-skill-manager"},
            "deliveryType": {"stringValue": "node"},
            "version": {"stringValue": str(sk.get("version") or "")},
            "audience": {"stringValue": str(sk.get("audience") or "dueño")},
            "needsOwnerData": {"booleanValue": bool(sk.get("needsOwnerData"))},
            "displayNameI18n": _i18n(m.get("displayName")),
            "summaryI18n": _i18n(m.get("summary")),
            "forClientsI18n": _i18n(m.get("forClients")),
            "whyOwnerOnlyI18n": _i18n(m.get("whyOwnerOnly")),
            "allowedAgents": {"arrayValue": {"values": [{"stringValue": a} for a in (sk.get("allowedAgents") or ["main"])]}},
            "clientTools": {"arrayValue": {"values": [{"stringValue": t} for t in ((sk.get("client") or {}).get("tools") or [])]}},
            "origin": {"stringValue": str(sk.get("origin") or "catalog")},
            "needsReview": {"booleanValue": bool(sk.get("needsReview"))},
            "agents": {"mapValue": {"fields": agents}},
            "skillsUpdatedAt": {"timestampValue": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())},
        }
        mask = "&".join("updateMask.fieldPaths=" + urllib.parse.quote(k, safe="") for k in fields)
        try:
            _http_request("PATCH", f"{base}/{sk['name']}?{mask}", payload={"fields": fields},
                          headers={"Authorization": f"Bearer {token['idToken']}"}, timeout=30)
            ok += 1
        except Exception as e:  # noqa: BLE001
            _log(f"skills-mirror: {sk['name']}: {e}")
    # 2.3.1: poda — docs MÍOS (managedBy) cuya skill ya no está en el state
    # (uninstall, o un skill del Taller retirado) se borran; si no, el app
    # los seguiría pintando para siempre.
    try:
        q = {"structuredQuery": {
            "from": [{"collectionId": "installed_skills"}],
            "where": {"fieldFilter": {"field": {"fieldPath": "managedBy"}, "op": "EQUAL",
                                      "value": {"stringValue": "tnode-skill-manager"}}},
            "select": {"fields": [{"fieldPath": "skillId"}]}}}
        parent = f"{_firestore_base()}/users/{token['uid']}/nodes/{cfg['nodeId']}"
        res = _http_request("POST", f"{parent}:runQuery", payload=q,
                            headers={"Authorization": f"Bearer {token['idToken']}"}, timeout=30)
        have = {sk["name"] for sk in rows}
        pruned = 0
        for item in (res if isinstance(res, list) else []):
            doc = item.get("document") or {}
            name_path = doc.get("name") or ""
            sid = name_path.rsplit("/", 1)[-1]
            if sid and sid not in have:
                _http_request("DELETE", f"{_firestore_base().split('/documents')[0]}/documents/{name_path.split('/documents/',1)[1]}",
                              headers={"Authorization": f"Bearer {token['idToken']}"}, timeout=30)
                pruned += 1
        if pruned:
            _log(f"skills-mirror: {pruned} docs podados (skills retirados)")
    except Exception as e:  # noqa: BLE001
        _log(f"skills-mirror: poda: {e}")
    _MIRROR_SKILLS_LAST_SIG = sig
    _log(f"skills-mirror: {ok}/{len(rows)} docs en installed_skills")


def _ensure_workspace_skills() -> None:
    """Materializa los skills de workspace en cada arranque (self-heal).
    2.0.0: delega en `tnode-skill-manager sync` — cache local → workspace de
    cada agente, idempotente, repara drift. Si el CLI o el cache no están
    (nodo pre-2.0 a medio migrar) sólo se loguea: el resto del boot sigue."""
    res = _run_skill_manager("sync")
    if res.get("ok"):
        if res.get("installed") or res.get("updated") or res.get("repaired"):
            _log("skills: %s" % res.get("summary"))
    else:
        _log("skills: sync falló: %s" % (res.get("error") or res.get("summary") or res)[:200])
    _sync_client_skills()


# ── Guest agent (Opción B: per-guest isolation) ──────────────────────────
# Invite-link visitors ("guests") run on a DEDICATED `guest` agent with its
# own NEUTRAL workspace, so they never load the owner's main workspace
# (USER.md/MEMORY.md/memory) — the root cause of the owner-identity leak.
# tnode-chat-sync routes `tnode-guest-*` sessions to this agent via the
# `agent:guest:` sessionKey prefix (the gateway honors it). The workspace is
# STATIC + neutral (warm business-attention, NO owner PII); the per-node /
# per-guest identity is injected at runtime by the tbrain-context-engine
# plugin (before_prompt_build). Model inherits the node default (no override).
_GUEST_WS_DIR = OPENCLAW_DIR / "workspace-guest"
_GUEST_AGENT_DIR = _AGENTS_DIR / "guest" / "agent"

# Guard-rails Layer 1 (#2.2): per-agent deny floor for ALL guests. Blocks the
# tools that could reach the OWNER's system/data (the guest runs with the node's
# owner-scoped creds + sandbox off): shell, filesystem, session/subagent
# control, channel messaging, canvas, and browser (SSRF). Leaves public-facing
# tools (web_search/web_fetch/image_generate/tts/huggingface). Per-link
# refinement is layered on top by the context-engine before_tool_call hook.
_GUEST_TOOLS_DENY = [
    "exec", "process",
    "read", "write", "edit", "file_write", "file_fetch", "dir_list", "dir_fetch",
    # P3 (#2.2): sessions_spawn/sessions_send LIFTED from the floor — delegation is
    # now gated per-link by the context-engine hook (guardRails.allowedAgents),
    # default-deny. Session introspection stays denied (no enumerating sessions).
    "sessions_list", "sessions_history",
    "sessions_yield", "session_status", "subagents", "agents_list",
    "message", "canvas", "browser",
    # P5: raw wiki tools blocked for all guests; kb_search (context-engine) is
    # the gated replacement — only available when allowedDocRefs is non-empty.
    "wiki_search", "wiki_get", "wiki_lint", "wiki_apply",
    # Hardening (2026-07-01): a guest must NEVER reach the owner's memory or the
    # node's control plane. These are hard-denied in the FLOOR (defense in depth
    # even if the context-engine hook fails to load) and are NOT togglable per
    # link — no legitimate guest use. `memory_*` = owner's private memory;
    # `gateway` = restart/config the running process; `cron` = schedule wake
    # events. (sessions_spawn/send stay OUT of the floor by design — delegation
    # is gated per-link by the hook via allowedAgents.)
    "memory_search", "memory_get", "gateway", "cron",
    # F3 (#3): outbound tools are OWNER-side (they expose every prospect's
    # profile and can message other guests). Hard-denied for guests — the
    # plugin handlers also refuse guest sessions; this floor is the net.
    "prospects_search", "guest_send",
]

